bool write_data_with_check(std::vector<uint8_t>& buffer, uint32_t header, const std::vector<uint32_t>& items) {
    // Create buffer adaptor with init_empty to start with empty buffer
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer, hexi::init_empty);

    // Check available space (header + size prefix + items)
    const size_t required_space = sizeof(uint32_t) + sizeof(uint32_t) + items.size() * sizeof(uint32_t);

    // Reserve space if needed
    adaptor.reserve(required_space);

    // Create binary stream for writing
    hexi::binary_stream<decltype(adaptor)> stream(adaptor);

    // Write header
    stream << header;

    // Write container data (automatically prefixed with size)
    stream << hexi::prefixed(items);

    // Check if write was successful
    return stream.good();
}
```

