```cpp
#include <hexi/allocators/block_allocator.h>
#include <iostream>
#include <cstdint>

// Note: push() and pop() are private, but we can observe their behavior
// through allocate() and deallocate() operations
template<size_t element_count = 10>
void demonstrate_block_allocator_behavior() {
    // Create a block_allocator for uint64_t with specified capacity
    hexi::block_allocator<std::uint64_t, element_count> allocator;

    std::cout << "=== Block Allocator Free List Behavior Demo ===" << std::endl;
    std::cout << "Initial state - free list initialized with " << element_count << " blocks\n\n";

    // Allocate blocks - internally calls pop() to remove from free list
    std::cout << "Phase 1: Allocating 3 blocks (internally calls pop())" << std::endl;
    auto* block1 = allocator.allocate(100);
    auto* block2 = allocator.allocate(200);
    auto* block3 = allocator.allocate(300);

    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "  Storage active: " << allocator.storage_active_count << std::endl;
    std::cout << "  Total allocs: " << allocator.total_allocs << std::endl;
    std::cout << "  Active count: " << allocator.active_count << std::endl;
    #endif

    // Deallocate blocks - internally calls push() to add back to free list
    std::cout << "\nPhase 2: Deallocating block2 (internally calls push())" << std::endl;
    allocator.deallocate(block2);

    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "  Storage active: " << allocator.storage_active_count << std::endl;
    std::cout << "  Total deallocs: " << allocator.total_deallocs << std::endl;
    std::cout << "  Active count: " << allocator.active_count << std::endl;
    #endif

    std::cout << "\nPhase 3: Deallocating block1 (internally calls push())" << std::endl;
    allocator.deallocate(block1);

    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "  Storage active: " << allocator.storage_active_count << std::endl;
    std::cout << "  Total deallocs: " << allocator.total_deallocs << std::endl;
    #endif

    // Re-allocate - will pop from free list in LIFO order
    std::cout << "\nPhase 4: Re-allocating (pops from free list - LIFO order)" << std::endl;
    auto* block4 = allocator.allocate(400);
    std::cout << "  block4 should reuse block1's memory (last pushed)" << std::endl;

    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "  Storage active: " << allocator.storage_active_count << std::endl;
    std::cout << "  Total allocs: " << allocator.total_allocs << std::endl;
    #endif

    // Clean up remaining allocations
    allocator.deallocate(block3);
    allocator.deallocate(block4);

    std::cout << "\n=== Free List Behavior Summary ===" << std::endl;
    std::cout << "- push(): Adds block to HEAD of free list (LIFO)" << std::endl;
    std::cout << "- pop(): Removes and returns HEAD block from free list" << std::endl;
    std::cout << "- Free list is a singly-linked list using free_block struct" << std::endl;
    std::cout << "- Each free_block has a 'next' pointer to form the chain" << std::endl;

    #ifdef HEXI_DEBUG_ALLOCATORS
    std::cout << "\nFinal Stats:" << std::endl;
    std::cout << "  Total allocs: " << allocator.total_allocs << std::endl;
    std::cout << "  Total deallocs: " << allocator.total_deallocs << std::endl;
    std::cout << "  Active count: " << allocator.active_count << std::endl;
    #endif
}
```

This implementation demonstrates how the `block_allocator`'s free list works through its public `allocate()` and `deallocate()` methods, which internally use the private `push()` and `pop()` methods to manage the LIFO free list.

