template<typename T>
void peek_value_from_buffer(pmc::buffer_adaptor<std::vector<std::byte>>& buffer, T& value) {
    // Use the template version of copy() to copy a single value without advancing read pointer
    buffer.copy(&value);
}

bool peek_and_compare(pmc::buffer_adaptor<std::vector<std::byte>>& buffer, const void* expected, std::size_t length) {
    // Allocate temporary buffer to hold peeked data
    std::vector<std::byte> temp(length);

    // Peek data without consuming it
    buffer.copy(temp.data(), length);

    // Compare peeked data with expected data
    return std::memcmp(temp.data(), expected, length) == 0;
}
