```python
# function_implementation_file
import json
import pickle
from pathlib import Path
from typing import Any, Dict, List


def get_passages_by_field_values(
    index_path: str,
    field_name: str,
    field_values: List[Any]
) -> List[Dict[str, Any]]:
    """Retrieve all passages from an index where a metadata field matches any value in a list.

Args:
    index_path: Path to the index file
    field_name: Metadata field name to filter by
    field_values: List of field values to match (passages matching any value will be returned)

Returns:
    List of passage dictionaries that have the field matching any value in field_values

Raises:
    FileNotFoundError: If index metadata file is not found
    ValueError: If field_values is empty"""

    # Validate field_values is not empty
    if not field_values:
        raise ValueError("field_values cannot be empty")

    # Construct metadata file path
    meta_path_str = f"{index_path}.meta.json"

    # Check if metadata file exists
    if not Path(meta_path_str).exists():
        raise FileNotFoundError(f"Index metadata file not found: {meta_path_str}")

    # Load metadata
    with open(meta_path_str, encoding="utf-8") as f:
        meta_data = json.load(f)

    # Get passage sources from metadata
    passage_sources = meta_data.get("passage_sources", [])

    # Process each passage source and collect passages
    matching_passages = []

    for source in passage_sources:
        if source["type"] != "jsonl":
            continue

        # Resolve passage file and index file paths
        passage_file = source.get("path", "")
        index_file = source.get("index_path", "")

        # Resolve paths relative to metadata file directory
        meta_dir = Path(meta_path_str).parent

        if not Path(passage_file).is_absolute():
            passage_file = str(meta_dir / passage_file)
        if not Path(index_file).is_absolute():
            index_file = str(meta_dir / index_file)

        # Check if index file exists
        if not Path(index_file).exists():
            raise FileNotFoundError(f"Passage index file not found: {index_file}")

        # Load offset map
        with open(index_file, "rb") as f:
            offset_map: Dict[str, int] = pickle.load(f)

        # Iterate through all passages in this source
        with open(passage_file, encoding="utf-8") as f:
            for passage_id, offset in offset_map.items():
                f.seek(offset)
                passage_data = json.loads(f.readline())

                # Check if field matches any value in field_values
                metadata = passage_data.get("metadata", {})

                # Check both top-level and metadata for the field
                field_value = passage_data.get(field_name)
                if field_value is None:
                    field_value = metadata.get(field_name)

                # If field value matches any in the list, add to results
                if field_value in field_values:
                    matching_passages.append(passage_data)

    return matching_passages
```

